// Assembles the self-contained database test files in supabase/tests/*.sql from supabase/tests/src/:
// each output = begin; + the shared prelude (helpers + base fixtures) + the test body + a final 'ok' row + rollback;
// Usage: node scripts/build-db-tests.mjs   (then run the generated files, see supabase/tests/README.md)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const srcDir = path.join(root, 'supabase/tests/src');
const outDir = path.join(root, 'supabase/tests');
const prelude = fs.readFileSync(path.join(srcDir, '_prelude.sql'), 'utf8').trimEnd();

const isSuite = (f) => /^\d\d_.*\.sql$/.test(f);
const sources = fs.readdirSync(srcDir).filter(isSuite).sort();

// A generated suite whose source was removed or renamed would keep running (and failing) under its old name.
for (const file of fs.readdirSync(outDir).filter(isSuite)) {
  if (!sources.includes(file)) {
    fs.rmSync(path.join(outDir, file));
    console.log(`removed supabase/tests/${file} (no source)`);
  }
}

for (const file of sources) {
  const name = file.replace(/\.sql$/, '');
  const body = fs.readFileSync(path.join(srcDir, file), 'utf8').trimEnd();
  const out = [
    `-- GENERATED by scripts/build-db-tests.mjs from supabase/tests/src/${file} + src/_prelude.sql — edit the sources, not this file.`,
    '-- Self-contained: everything runs inside one transaction that is rolled back. Fails loudly (RAISE) on the first wrong',
    "-- allow/deny or broken rule; prints a single 'ok' row when every check passed. See supabase/tests/README.md.",
    'begin;',
    prelude,
    '',
    body,
    '',
    `select 'ok' as result, '${name}' as test;`,
    'rollback;',
    '',
  ].join('\n');
  fs.writeFileSync(path.join(outDir, file), out);
  console.log(`wrote supabase/tests/${file} (${out.length} chars)`);
}
